  'settings.general.artistInfoSources.description': 'Choose the encyclopedia sources used when refreshing artist bios. Baidu Baike fits Chinese network contexts better, while Wikipedia can backstop international artists.',
  'settings.general.artistInfoSources.title': 'Artist Info Sources',
  'settings.general.artistStreamingAlbums.description': 'When enabled, artist detail pages can search for and show streaming albums below local albums on demand. On by default; turn it off to avoid extra page and network pressure.',
  'settings.general.artistStreamingAlbums.title': 'Streaming Albums',
  'settings.general.osuDownloaderFeature.description': 'Off by default. Enable to show osu! in the sidebar for beatmap search and audio extraction through the downloads flow.',
  'settings.general.osuDownloaderFeature.title': 'osu! entry',
  'settings.general.streamingFeature.description': 'On by default. Disable to hide the Streaming page from the sidebar; online music search and favorites still require accepting the streaming feature notice first.',
  'settings.general.streamingFeature.title': 'Streaming Entry',
  'streamingConsentNotice.acceptance': 'Continuing means you understand and accept that this feature is a personal local-client helper. It is not legal advice, a copyright license, a platform agency relationship, or a promise that any content will be available.',
  'streamingConsentNotice.authorizedUse': 'You must only use accounts, subscriptions, and content you are authorized to access. Do not use this feature to bypass platform terms, download limits, DRM, account risk controls, paywalls, or copyright protections.',
  'streamingConsentNotice.bodyIntro': 'The ECHO Next streaming entry only integrates search, account status, favorites, playlist import, and playback entry points. ECHO does not own, host, sell, or redistribute copyrights to audio, video, artwork, lyrics, or metadata from any third-party streaming platform.',
  'streamingConsentNotice.cancel': 'Cancel',
  'streamingConsentNotice.close': 'Close notice',
  'streamingConsentNotice.confirm': 'I agree and continue',
  'streamingConsentNotice.consentPhrase': 'I agree',
  'streamingConsentNotice.disclaimer': 'Disclaimer: ECHO is not liable for account restrictions, service interruptions, copyright disputes, DMCA notices, data loss, regional unavailability, or other losses caused by your use of third-party platforms.',
  'streamingConsentNotice.dmca': 'DMCA is a notice-and-takedown mechanism under United States copyright law. If a rightsholder believes that content, links, or data usage infringes their rights, they should submit a notice through the relevant platform or lawful channel. Users should also stop the relevant use when receiving a rightsholder notice or platform request.',
  'streamingConsentNotice.inputLabel': 'Type "{phrase}" to continue',
  'streamingConsentNotice.license': 'ECHO code and plugins are governed by the project license. Cracking, bypassing authorization, forging entitlements, removing integrity checks, or using ECHO as a tool for unauthorized access to paid content is prohibited.',
  'streamingConsentNotice.localFirst': 'ECHO is fundamentally a local music player, and streaming has the lowest product priority. Requests to add a specific platform or audio source will be refused. If streaming has problems, use your local music library first.',
  'streamingConsentNotice.noBypass': 'ECHO will not provide any platform with membership bypass, preview cracking, payment evasion, or anything that harms the interests of platforms or rightsholders. If a song only plays for 30 seconds, check your platform membership, subscription, region, and account status.',
  'streamingConsentNotice.platformControl': 'Third-party platforms, trademarks, catalogs, APIs, accounts, subscriptions, cookies, DRM, regional restrictions, and playback authorization are controlled by the relevant platforms and rightsholders. ECHO does not represent those platforms and does not grant any license to platform content.',
  'streamingConsentNotice.title': 'Streaming Feature Notice',
  'streamingConsentNotice.uninstall': 'If you think streaming platform memberships are too expensive, stop using this feature and uninstall the software. Requests to crack memberships, bypass authorization, evade copyright protections, or perform other unlawful actions will be refused.',
